const r = await tools.exec_command({cmd:""$STAMPED_ASSESSMENT_PYTHON" "$STAMPED_ASSESSMENT_RUNNER" probes --help; "$STAMPED_ASSESSMENT_PYTHON" "$STAMPED_ASSESSMENT_RUNNER" response --help; "$STAMPED_ASSESSMENT_PYTHON" "$STAMPED_ASSESSMENT_RUNNER" validate --help; "$STAMPED_ASSESSMENT_PYTHON" - <<'PY'
import json,os
from pathlib import Path
for env in ['STAMPED_WORKER_STOP_RECEIPT','STAMPED_DELIVERY_MANIFEST']:
 p=Path(os.environ[env]); d=json.loads(p.read_text())
 print('\n',env)
 if env=='STAMPED_WORKER_STOP_RECEIPT':
  def walk(x,prefix=''):
   if isinstance(x,dict):
    for k,v in x.items():
     if isinstance(v,(str,int,float,bool)) or v is None: print(prefix+k,repr(v)[:300])
     else: walk(v,prefix+k+'.')
   elif isinstance(x,list): print(prefix,'list',len(x))
  walk(d)
PY
cat "$STAMPED_JUDGE_TARGET/results/summary.json"; find "$STAMPED_JUDGE_TARGET" -maxdepth 2 -type f \( -name 'pyproject.toml' -o -name 'requirements*.txt' -o -name 'pixi.toml' -o -name 'environment.yml' -o -name 'Dockerfile' -o -name 'README*' \) -print","yield_time_ms":10000,"max_output_tokens":6500});
text(r.output);

